-- 1) ძველი აღწერების ასლი (დაბრუნებისთვის)
CREATE TABLE IF NOT EXISTS superi_bk_product_meta AS SELECT pd.product_id, pd.lang_code, pd.meta_description FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_targets t ON t.name = s.name WHERE pd.lang_code = 'ka';

-- 2) ახალი აღწერა
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_targets t ON t.name = s.name
SET pd.meta_description = CONCAT('შეიძინეთ ', TRIM(pd.product), ' Superi.ge-ზე: ✓ ნაწილ-ნაწილ გადახდა ✓ უფასო მიწოდება თბილისში 100₾-დან ✓ მიწოდება მთელ საქართველოში.')
WHERE pd.lang_code = 'ka' AND TRIM(pd.product) <> '';

-- 3) უხილავი სიმბოლოები (U+200B) აღწერებსა და სათაურებში
SET @zw := CONVERT(UNHEX('E2808B') USING utf8mb4);
UPDATE cscart_product_descriptions SET meta_description = REPLACE(meta_description, @zw, ''), page_title = REPLACE(page_title, @zw, '') WHERE lang_code = 'ka' AND (INSTR(meta_description, @zw) > 0 OR INSTR(page_title, @zw) > 0);

-- 4) სათაურებში "|"-ის ირგვლივ ჰარები ("X|Superi.ge" -> "X | Superi.ge")
UPDATE cscart_product_descriptions SET page_title = REGEXP_REPLACE(page_title, '[[:space:]]*[|][[:space:]]*', ' | ') WHERE lang_code = 'ka' AND page_title REGEXP '[^[:space:]][|]|[|][^[:space:]]';

-- 5) შემოწმება
SELECT COUNT(*) AS updated_with_template FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' JOIN tmp_targets t ON t.name = s.name WHERE pd.lang_code = 'ka' AND pd.meta_description LIKE 'შეიძინეთ %ნაწილ-ნაწილ გადახდა%';
DROP TEMPORARY TABLE IF EXISTS tmp_targets;

